"""H1-HUNTER SDR - button icons as small PNG images (drawn, not font characters: they look the same on every
computer and operating system)."""
import tkinter as tk

_PNG = {
    "refresh_light": "",
    "stop_red": "",
    "play": "",
    "stop": "",
    "check": "",
    "save": "",
    "package": "",
    "refresh": "",
}


def load_icons():
    """{name: tk.PhotoImage}. Keep the dictionary: Tk shows an image only while Python holds a reference."""
    out = {}
    for k, b in _PNG.items():
        try:
            out[k] = tk.PhotoImage(data=b)
        except Exception:
            pass
    return out
